"""Tools for the travel agent. @tool turns a typed, documented function into a tool."""
from langchain.tools import tool

# Fake data so the project runs without real travel APIs
_WEATHER = {"goa": "Sunny, 31 C, low chance of rain", "delhi": "Hazy, 24 C", "mumbai": "Humid, 30 C"}
_FLIGHTS = [
    {"id": "AI-101", "origin": "delhi", "destination": "goa", "depart": "06:10", "price_inr": 6450},
    {"id": "6E-552", "origin": "delhi", "destination": "goa", "depart": "09:45", "price_inr": 5120},
    {"id": "UK-873", "origin": "delhi", "destination": "goa", "depart": "18:30", "price_inr": 7300},
]


@tool
def get_weather(city: str) -> str:
    """Get the weather forecast for a destination city. Call this before searching flights."""
    # The docstring and type hints become the tool schema the model sees
    return _WEATHER.get(city.strip().lower(), f"No forecast available for {city}.")


@tool
def search_flights(origin: str, destination: str, date: str) -> str:
    """Search flights from origin to destination on a date (YYYY-MM-DD). Returns flight IDs and prices in INR."""
    matches = [
        f for f in _FLIGHTS
        if f["origin"] == origin.strip().lower() and f["destination"] == destination.strip().lower()
    ]
    if not matches:
        return f"No flights found from {origin} to {destination} on {date}."
    lines = [f"{f['id']} departs {f['depart']} on {date}, Rs {f['price_inr']}" for f in matches]
    return "\n".join(lines)


@tool
def book_flight(flight_id: str, passenger_name: str) -> str:
    """Book a flight by its ID for a passenger. Only call when the user clearly asks to book."""
    # HumanInTheLoopMiddleware pauses the agent before this tool runs
    if flight_id not in {f["id"] for f in _FLIGHTS}:
        return f"Unknown flight ID {flight_id}."
    return f"Booked {flight_id} for {passenger_name}. PNR: TRV{abs(hash(flight_id)) % 10000:04d}"


ALL_TOOLS = [get_weather, search_flights, book_flight]

